     1	//! Axum router. Paths, statuses and bodies come from tech.md section 6.2.
     2	
     3	use std::sync::Arc;
     4	use std::time::{Duration, SystemTime, UNIX_EPOCH};
     5	
     6	use axum::{
     7	    extract::{Path, State},
     8	    http::StatusCode,
     9	    response::{IntoResponse, Response},
    10	    routing::{get, post},
    11	    Json, Router,
    12	};
    13	use peekle_core::types::{PromptOutcome, PromptRequest};
    14	use serde_json::{json, Value};
    15	use ulid::Ulid;
    16	
    17	use crate::map;
    18	use crate::sink::HookSink;
    19	
    20	/// Reported by `/v1/health`. Tracks the core version in the tech.md header.
    21	pub const CORE_VERSION: &str = "v7";
    22	
    23	#[derive(Clone)]
    24	pub struct ServerState {
    25	    pub sink: Arc<dyn HookSink>,
    26	    pub token: String,
    27	    pub version: String,
    28	}
    29	
    30	pub fn router(state: ServerState) -> Router {
    31	    Router::new()
    32	        .route("/v1/health", get(health))
    33	        .route("/v1/h/{token}/stop", post(stop))
    34	        .route("/v1/h/{token}/permission", post(permission))
    35	        .route("/v1/h/{token}/notification", post(notification))
    36	        .route("/v1/h/{token}/tasks", post(tasks))
    37	        .route("/v1/h/{token}/session", post(session))
    38	        .with_state(state)
    39	}
    40	
    41	/// `200 {}` is the answer to almost everything: no decision, turn continues as
    42	/// if Peekle were not installed.
    43	fn empty() -> Response {
    44	    (StatusCode::OK, Json(json!({}))).into_response()
    45	}
    46	
    47	/// A bad token is indistinguishable from a wrong path on purpose, and the
    48	/// value never reaches a log line.
    49	fn not_found() -> Response {
    50	    StatusCode::NOT_FOUND.into_response()
    51	}
    52	
    53	fn check_token(state: &ServerState, token: &str) -> bool {
    54	    token == state.token
    55	}
    56	
    57	/// The body arrives as raw bytes so a malformed payload answers 400 instead of
    58	/// letting axum's own rejection shape leak out.
    59	fn parse(body: &[u8]) -> Result<Value, StatusCode> {
    60	    serde_json::from_slice(body).map_err(|_| StatusCode::BAD_REQUEST)
    61	}
    62	
    63	fn now_ms() -> i64 {
    64	    SystemTime::now()
    65	        .duration_since(UNIX_EPOCH)
    66	        .map(|d| d.as_millis() as i64)
    67	        .unwrap_or_default()
    68	}
    69	
    70	async fn health(State(state): State<ServerState>) -> Response {
    71	    Json(json!({
    72	        "version": state.version,
    73	        "enabled": state.sink.is_enabled(),
    74	        "core": CORE_VERSION,
    75	    }))
    76	    .into_response()
    77	}
    78	
    79	/// Shared path for both blocking endpoints: build the request, hand it to the
    80	/// sink, wait no longer than the configured timeout, map the outcome.
    81	async fn blocking(
    82	    state: ServerState,
    83	    token: String,
    84	    body: bytes::Bytes,
    85	    build: fn(String, &Value, i64, i64) -> PromptRequest,
    86	    render: fn(&PromptOutcome, &PromptRequest) -> Value,
    87	) -> Response {
    88	    if !check_token(&state, &token) {
    89	        return not_found();
    90	    }
    91	    let payload = match parse(&body) {
    92	        Ok(payload) => payload,
    93	        Err(status) => return status.into_response(),
    94	    };
    95	
    96	    // Off short-circuits before any window work. The agent runs in its normal
    97	    // mode and nothing is left pending.
    98	    if !state.sink.is_enabled() {
    99	        return empty();
   100	    }
   101	
   102	    let timeout = state.sink.prompt_timeout();
   103	    let now = now_ms();
   104	    let request = build(
   105	        Ulid::generate().to_string(),
   106	        &payload,
   107	        now,
   108	        now + timeout.as_millis() as i64,
   109	    );
   110	
   111	    let receiver = state.sink.open_prompt(request.clone());
   112	    let outcome = match tokio::time::timeout(timeout, receiver).await {
   113	        Ok(Ok(outcome)) => outcome,
   114	        // Timed out, or the sender was dropped without an answer. Either way
   115	        // the request is settled and the turn ends normally.
   116	        Ok(Err(_)) | Err(_) => PromptOutcome::TimedOut,
   117	    };
   118	
   119	    (StatusCode::OK, Json(render(&outcome, &request))).into_response()
   120	}
   121	
   122	async fn stop(
   123	    State(state): State<ServerState>,
   124	    Path(token): Path<String>,
   125	    body: bytes::Bytes,
   126	) -> Response {
   127	    blocking(state, token, body, map::stop_request, map::stop_body).await
   128	}
   129	
   130	async fn permission(
   131	    State(state): State<ServerState>,
   132	    Path(token): Path<String>,
   133	    body: bytes::Bytes,
   134	) -> Response {
   135	    blocking(
   136	        state,
   137	        token,
   138	        body,
   139	        map::permission_request,
   140	        map::permission_body,
   141	    )
   142	    .await
   143	}
   144	
   145	/// Non-blocking feeds. They keep collecting while Peekle is off, because the
   146	/// The feed and the session registry stay alive in bypass mode.
   147	async fn feed(
   148	    state: ServerState,
   149	    token: String,
   150	    body: bytes::Bytes,
   151	    deliver: fn(&dyn HookSink, &Value),
   152	) -> Response {
   153	    if !check_token(&state, &token) {
   154	        return not_found();
   155	    }
   156	    match parse(&body) {
   157	        Ok(payload) => {
   158	            deliver(state.sink.as_ref(), &payload);
   159	            empty()
   160	        }
   161	        Err(status) => status.into_response(),
   162	    }
   163	}
   164	
   165	async fn notification(
   166	    State(state): State<ServerState>,
   167	    Path(token): Path<String>,
   168	    body: bytes::Bytes,
   169	) -> Response {
   170	    feed(state, token, body, |sink, payload| {
   171	        sink.on_notification(payload)
   172	    })
   173	    .await
   174	}
   175	
   176	async fn tasks(
   177	    State(state): State<ServerState>,
   178	    Path(token): Path<String>,
   179	    body: bytes::Bytes,
   180	) -> Response {
   181	    feed(state, token, body, |sink, payload| sink.on_tasks(payload)).await
   182	}
   183	
   184	async fn session(
   185	    State(state): State<ServerState>,
   186	    Path(token): Path<String>,
   187	    body: bytes::Bytes,
   188	) -> Response {
   189	    feed(state, token, body, |sink, payload| sink.on_session(payload)).await
   190	}
   191	
   192	/// Convenience for callers that want a ready-made timeout.
   193	pub fn default_timeout() -> Duration {
   194	    Duration::from_secs(600)
   195	}
