     1	//! The seam between the hook endpoints and the rest of the app.
     2	//!
     3	//! The router owns no state. It parses a hook, asks the sink for a decision
     4	//! channel, and turns the outcome into a response body. That keeps the whole
     5	//! HTTP contract of section 6.2 testable without a running Tauri app.
     6	
     7	use std::time::Duration;
     8	
     9	use peekle_core::types::{PromptOutcome, PromptRequest};
    10	use serde_json::Value;
    11	use tokio::sync::oneshot;
    12	
    13	pub trait HookSink: Send + Sync + 'static {
    14	    /// When Peekle is off, every blocking endpoint answers `200 {}` before any
    15	    /// window work happens. tech.md section 8.
    16	    fn is_enabled(&self) -> bool;
    17	
    18	    /// Registers a pending request and returns the channel it resolves on.
    19	    /// The registry, not the router, owns the resolve-exactly-once invariant.
    20	    fn open_prompt(&self, request: PromptRequest) -> oneshot::Receiver<PromptOutcome>;
    21	
    22	    /// Held below the hook timeout so Peekle always answers first.
    23	    fn prompt_timeout(&self) -> Duration;
    24	
    25	    /// Non-blocking feeds. These never hold up a turn, so they take the raw
    26	    /// payload and return nothing.
    27	    fn on_tasks(&self, payload: &Value);
    28	    fn on_session(&self, payload: &Value);
    29	    fn on_notification(&self, payload: &Value);
    30	}

